import argparse,hashlib,json,re,statistics,subprocess,os
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--fixtures',nargs='+',default=['order-book','clipped-ticker','reflow-cards','canvas-market','live-board','orbit-wall','canvas-atlas']);p.add_argument('--rounds',type=int,default=3);p.add_argument('--out',default='measure');args=p.parse_args()
root=Path('/private/tmp/widget-stress-round9');out=root/args.out;out.mkdir(exist_ok=True)
repo=Path('/Users/renoir/projects/Telegram/telegrammacos');runs=[]
for r in range(args.rounds):
 for name in args.fixtures:
  for variant in (['before','after','webkit'] if r%2==0 else ['webkit','after','before']):
   lab=root/('TwidgetLab-before' if variant=='before' else 'TwidgetLab-final')
   stem=f'{name}-{variant}-{r+1}'
   cmd=[str(lab),'capture',str(repo/'tools/perflab/widget-stress'/f'{name}.html'),'--renderer','web' if variant=='webkit' else 'lite','--out',str(out/stem),'--width','480','--max-height','6000','--theme','dark','--seconds','8','--warmup','2','--cpu','--memory','--logs']
   env=dict(os.environ);env['TW_LOCAL_PAINT_REUSE']='1';env['TW_SCROLL_COMPOSITOR_TAKEOVER']='0';env['TW_SCROLL_BATCH_COMMITS']='1';env['TW_SCROLL_SKIP_OBSOLETE']='1'
   result=subprocess.run(cmd,env=env,capture_output=True,text=True,timeout=90);log=result.stdout+result.stderr;(out/f'{stem}.log').write_text(log)
   if result.returncode or 'log error:' in log or not re.search(r'rendered=true dead=- error=-',log):raise SystemExit(f'Failed {stem}: {log[-2000:]}')
   m=re.search(r'steady: own ([\d.]+)% helpers ([\d.]+)% total ([\d.]+)% windowserver ([\d.]+)% over ([\d.]+)s ops (\d+) fps ([\d.]+) cpu/frame ([\d.]+) ms',log)
   if not m:raise SystemExit(f'Missing measurements: {stem}')
   d=dict(zip(['own_cpu','helpers_cpu','total_cpu','windowserver_cpu','seconds','ops','host_fps','cpu_ms_per_host_frame'],map(float,m.groups())))
   d.update(fixture=name,variant=variant,run=r+1)
   memory=re.search(r'end own ([\d.]+) helpers ([\d.]+)',log)
   if memory:d['footprint_mb']=sum(map(float,memory.groups()))
   layouts=re.search(r'layouts=(\d+) total=([\d.]+) ms',log)
   if layouts:d.update(layouts=int(layouts[1]),layout_ms=float(layouts[2]))
   style_patch=re.search(r'style-patch ([\d.]+)',log)
   if style_patch:d['style_patch_ms_per_layout']=float(style_patch[1])
   tiles=re.search(r'tiles: batches/frame ([\d.]+) jobs/frame ([\d.]+).*?ms/job setup ([\d.]+) copy ([\d.]+) draw ([\d.]+)',log)
   if tiles:d.update(dict(zip(['tile_batches_per_callback','tile_jobs_per_callback','tile_setup_ms_per_job','tile_copy_ms_per_job','tile_draw_ms_per_job'],map(float,tiles.groups()))))
   runs.append(d);(out/'runs.json').write_text(json.dumps(runs,indent=2)+'\n')
   print(f'{stem}: {d["total_cpu"]:.2f}% CPU, {d["host_fps"]:.1f} host callbacks/s',flush=True)
summary=[]
for name in args.fixtures:
 for variant in ['before','after','webkit']:
  rows=[r for r in runs if r['fixture']==name and r['variant']==variant]
  row=dict(fixture=name,variant=variant,runs=len(rows))
  for key in ['total_cpu','host_fps','footprint_mb','layouts','layout_ms','style_patch_ms_per_layout','tile_batches_per_callback','tile_jobs_per_callback','tile_setup_ms_per_job','tile_copy_ms_per_job','tile_draw_ms_per_job']:
   values=[r[key] for r in rows if key in r]
   if values:row[key]=dict(median=statistics.median(values),min=min(values),max=max(values))
  summary.append(row)
report=dict(width=480,seconds=8,warmup=2,method='Serial baseline and optimized native binaries plus WebKit; reverse order in round two. Both native binaries enable the published scroll batching and obsolete-raster cancellation. Both retain canonical resolved paint exclusion caching. Selected uses guarded resolved fixed-flex layout reuse with explicit min/max and dependent subtree fallback. Decoration caching and scroll-image conversion were rejected and removed. Experimental scroll-owned takeover is disabled. Transport recording disabled. CPU is percent of one core, including WebKit helpers, excluding WindowServer. Host callbacks are not display FPS.',binary_sha256={name:hashlib.sha256((root/name).read_bytes()).hexdigest() for name in ['TwidgetLab-before','TwidgetLab-final']},fixture_sha256={name:hashlib.sha256((repo/'tools/perflab/widget-stress'/f'{name}.html').read_bytes()).hexdigest() for name in args.fixtures},rounds=args.rounds,summary=summary,runs=runs)
(out/'report.json').write_text(json.dumps(report,indent=2)+'\n')

