import json,re,statistics
from pathlib import Path
root=Path('/private/tmp/widget-stress-round9/live-final')
p=root/'report.json';d=json.loads(p.read_text())
for row in d['runs']:
    log=(root/(row['fixture']+'-'+row['variant']+'-'+str(row['run'])+'.log')).read_text()
    match=re.search(r'\| declarations .*?  layout ([\d.]+) ',log)
    if match: row['layout_stage_ms_per_layout']=float(match[1])
for row in d['summary']:
    values=[r['layout_stage_ms_per_layout'] for r in d['runs'] if r['fixture']==row['fixture'] and r['variant']==row['variant'] and 'layout_stage_ms_per_layout' in r]
    if values:row['layout_stage_ms_per_layout']=dict(median=statistics.median(values),min=min(values),max=max(values))
p.write_text(json.dumps(d,indent=2)+'\n')
print('Added per-layout stage medians from raw logs.')
